"use client";

import { useEffect, useId, useState, type ComponentProps, type ReactNode } from "react";

import { IconAlertCircle, IconCalendarCheck, IconSend } from "@rhs-ui/icons";
import {
  DEFAULT_LABELS,
  dayLabel,
  draftOf,
  fill,
  gmtLabel,
  instantOfDraft,
  isoAt,
  millisecondsOf,
  nextSlot,
  offsetAt,
  pad,
  relative,
  safeZone,
  wallAt,
  type Draft,
  type SendScheduleLabels,
  type SendScheduleValue,
} from "@rhs-ui/application/send-schedule-field/zone";
import { DateTimePicker } from "@rhs-ui/primitives/date-time-picker";
import { Label } from "@rhs-ui/primitives/label";
import { RadioGroup, RadioGroupItem } from "@rhs-ui/primitives/radio-group";
import { cn } from "@/lib/utils";

export type { SendScheduleLabels, SendScheduleValue } from "@rhs-ui/application/send-schedule-field/zone";

export interface SendScheduleFieldProps extends Omit<ComponentProps<"fieldset">, "value" | "defaultValue" | "onChange" | "children"> {
  /** What is chosen, when you control it. `at` is an ISO time with an offset ("2026-10-27T09:00:00+01:00"), and null while the day or the time is missing or was refused. */
  value?: SendScheduleValue;
  /** What is chosen to begin with, when the field keeps it itself. Default send now. */
  defaultValue?: SendScheduleValue;
  /** Called with the mode and the time whenever either changes. A time that is too soon is reported as `at: null`, so a Send button can wait for a good one. */
  onValueChange?: (value: SendScheduleValue) => void;
  /** The least time between now and the send, in minutes. Anything sooner is refused. Default 15. */
  minLeadMinutes?: number;
  /** The zone the times are read and written in, as an IANA name: the reader's own, usually. It is named under the pickers and in the sentence. Default "UTC". */
  timeZone?: string;
  /** Minutes between the times in the list. Default 15. */
  minuteStep?: number;
  /** The language of the dates and of "in 3 days". Default "en-US". */
  locale?: string;
  /** The moment to count from, as a Date, milliseconds or ISO text: for tests and previews. Default the browser's clock, read after the page has loaded, so the server and the browser agree. */
  now?: Date | number | string;
  /** What the group is called. It is the legend, so a screen reader names the group before the first choice. Default "When should it go out?" */
  legend?: ReactNode;
  /** Keep the legend for screen readers only, when the page has a heading of its own. */
  hideLegend?: boolean;
  /** The words the field says, for translation. */
  labels?: SendScheduleLabels;
}

interface OptionProps {
  id: string;
  value: "now" | "later";
  selected: boolean;
  title: string;
  hint: string;
  children?: ReactNode;
}

/** A choice as a card: the whole card is the click target, and what it reveals sits above that target so it stays usable. */
function Option({ id, value, selected, title, hint, children }: OptionProps) {
  return (
    <div
      data-state={selected ? "selected" : "idle"}
      className={cn("relative rounded-lg border p-4 transition-colors duration-150 motion-reduce:transition-none", selected ? "border-foreground bg-card" : "border-border hover:bg-muted/40")}
    >
      <div className="flex items-start gap-3">
        <RadioGroupItem id={id} value={value} aria-describedby={`${id}-hint`} className="mt-0.5" />
        <div className="grid min-w-0 gap-0.5">
          <Label htmlFor={id} className="text-sm leading-5 font-medium after:absolute after:inset-0 after:content-['']">
            {title}
          </Label>
          <p id={`${id}-hint`} className="text-sm leading-5 text-pretty text-muted-foreground">
            {hint}
          </p>
        </div>
      </div>
      {children}
    </div>
  );
}

/**
 * The choice at the end of a campaign, a post or an export: send now, or
 * schedule for later. Choosing Schedule opens a day and a time from the house
 * pickers. A time inside the lead time (`minLeadMinutes`, 15 by default) or in
 * the past is refused with a message that names the earliest time that works,
 * and is reported as `at: null`. A sentence under the choices always says the
 * result in the zone you give ("Goes out Tue 27 Oct at 09:00, Europe/Amsterdam,
 * in 3 days") in a polite live region, so a change is read out. The two
 * choices are a real radio group (arrow keys move and choose), and a time
 * comes back as an ISO string with the zone's offset at that moment, daylight
 * saving included. Pass `now` for a fixed clock; without it the field reads
 * the browser's clock once the page has loaded and every half minute after.
 */
export function SendScheduleField({
  value,
  defaultValue,
  onValueChange,
  minLeadMinutes = 15,
  timeZone = "UTC",
  minuteStep = 15,
  locale = "en-US",
  now,
  legend,
  hideLegend,
  disabled,
  labels,
  className,
  ...props
}: SendScheduleFieldProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const base = useId();
  const legendId = `${base}-legend`;
  const zone = safeZone(timeZone);
  const [own, setOwn] = useState<SendScheduleValue>(defaultValue ?? { mode: "now", at: null });
  const current = value ?? own;
  const [draft, setDraft] = useState<Draft>(() => draftOf(current.at, zone));
  const [seen, setSeen] = useState(current.at);
  const [clock, setClock] = useState<number | null>(null);

  // A time that arrives from outside replaces what was picked. What the field reported itself is already in `seen`.
  if (current.at !== seen) {
    setSeen(current.at);
    setDraft(draftOf(current.at, zone));
  }

  const fixed = now === undefined ? null : millisecondsOf(now);
  useEffect(() => {
    if (fixed !== null) return;
    setClock(Date.now());
    const timer = window.setInterval(() => setClock(Date.now()), 30_000);
    return () => window.clearInterval(timer);
  }, [fixed]);
  const nowMs = fixed ?? clock;

  const later = current.mode === "later";
  // The first time on the list that is far enough away: it is what the message names, and it is allowed. The list is laid out on the zone's clock, so it is rounded there.
  const earliest = nowMs === null ? null : nextSlot(nowMs + minLeadMinutes * 60_000, Math.max(1, minuteStep), zone);
  const instant = draft.date && draft.time ? instantOfDraft(draft.date, draft.time, zone) : null;
  const refused = later && instant !== null && earliest !== null && instant < earliest;
  const passed = refused && nowMs !== null && instant !== null && instant < nowMs;

  const whenOf = (at: number) => {
    const wall = wallAt(zone, at);
    return fill(text.at, { date: dayLabel(wall, locale), time: `${pad(wall.hour)}:${pad(wall.minute)}` });
  };
  const earliestLabel = earliest === null ? null : whenOf(earliest);

  function report(next: SendScheduleValue) {
    setSeen(next.at);
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  // The clock moving on can make a time that was fine too soon: tell the form, which then holds no time.
  useEffect(() => {
    if (refused && current.at !== null) {
      setSeen(null);
      if (value === undefined) setOwn({ mode: "later", at: null });
      onValueChange?.({ mode: "later", at: null });
    }
  }, [refused, current.at, value, onValueChange]);

  function choose(next: string) {
    const mode = next === "later" ? "later" : "now";
    const good = mode === "later" && instant !== null && (earliest === null || instant >= earliest);
    report({ mode, at: good && instant !== null ? isoAt(zone, instant) : null });
  }

  function pick(next: Draft) {
    setDraft(next);
    const at = next.date && next.time ? instantOfDraft(next.date, next.time, zone) : null;
    const good = at !== null && (earliest === null || at >= earliest);
    report({ mode: "later", at: good && at !== null ? isoAt(zone, at) : null });
  }

  // The offset the pickers are read at: the picked time, else the earliest one, else now.
  const reference = instant ?? earliest ?? nowMs;
  const offset = reference === null ? null : gmtLabel(offsetAt(zone, reference));
  const sentence = !later
    ? text.sentenceNow
    : current.at !== null && instant !== null
      ? fill(nowMs === null ? text.sentenceLaterQuiet : text.sentenceLater, { when: whenOf(instant), zone, relative: nowMs === null ? "" : relative(nowMs, instant, locale) })
      : refused
        ? text.sentenceRefused
        : text.sentencePick;
  const problem = !refused || !earliestLabel ? null : fill(passed ? text.past : text.soon, { when: earliestLabel });

  return (
    <fieldset data-slot="send-schedule-field" disabled={disabled} className={cn("@container m-0 min-w-0 border-0 p-0", className)} {...props}>
      <legend id={legendId} className={cn("p-0 text-sm font-medium", hideLegend ? "sr-only" : "mb-3")}>
        {legend ?? text.legend}
      </legend>

      <div className="grid gap-3">
        <RadioGroup value={current.mode} onValueChange={choose} aria-labelledby={legendId} className="gap-2.5">
          <Option id={`${base}-now`} value="now" selected={!later} title={text.now} hint={text.nowHint} />
          <Option id={`${base}-later`} value="later" selected={later} title={text.later} hint={text.laterHint}>
            {/* The pickers sit above the card's click target and out of the tab order until Schedule is chosen. */}
            <div className={cn("relative z-10 grid transition-[grid-template-rows] duration-200 motion-reduce:transition-none", later ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
              <div inert={!later} className="-mx-1 -mb-1 min-h-0 overflow-hidden px-1 pb-1">
                <div className="grid grid-cols-[minmax(0,1fr)] gap-2.5 pt-4 @md:pl-7">
                  {/* The picker puts day and time side by side from the screen's `sm`; here it does so from the field's own width, so a narrow card stacks them instead of cutting the time off. The triggers drop their minimum width (a day field is 12rem otherwise) so a field narrower than that shrinks them rather than being clipped, and the column above may shrink so the messages wrap. */}
                  <DateTimePicker
                    value={draft}
                    onValueChange={pick}
                    step={minuteStep}
                    min="00:00"
                    max="23:59"
                    locale={locale}
                    className="sm:grid-cols-1 @md:grid-cols-[1fr_auto] @max-md:[&_[data-slot=time-picker]]:w-full [&_[data-slot=date-picker]]:min-w-0 [&_[data-slot=time-picker]]:min-w-0"
                  />
                  {problem ? (
                    <p role="alert" className="flex items-start gap-2 text-sm leading-5 font-medium text-destructive">
                      <IconAlertCircle aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
                      {problem}
                    </p>
                  ) : earliestLabel ? (
                    <p className="text-xs text-muted-foreground">{fill(text.earliest, { when: earliestLabel })}</p>
                  ) : null}
                  <p className="text-xs text-muted-foreground">{offset === null ? fill(text.zoneOnly, { zone }) : fill(text.zoneNote, { zone, offset })}</p>
                </div>
              </div>
            </div>
          </Option>
        </RadioGroup>

        <div className="flex items-start gap-2.5 rounded-lg border border-border bg-muted/40 px-3.5 py-3">
          {later ? <IconCalendarCheck aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-muted-foreground" /> : <IconSend aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-muted-foreground" />}
          <p role="status" aria-live="polite" className={cn("min-w-0 text-sm leading-5", current.at !== null || !later ? "font-medium text-foreground" : "text-muted-foreground")}>
            {sentence}
          </p>
        </div>
      </div>
    </fieldset>
  );
}

/** The words the field says, for translation. A `{name}` mark in a sentence is filled in. */
export interface SendScheduleLabels {
  /** The legend. Default "When should it go out?" */
  legend?: string;
  /** The first choice. Default "Send now". */
  now?: string;
  /** The line under the first choice. Default "Sent immediately, nothing to schedule." */
  nowHint?: string;
  /** The second choice. Default "Schedule for later". */
  later?: string;
  /** The line under the second choice. Default "Pick the day and time it goes out." */
  laterHint?: string;
  /** Under the pickers; `{zone}` and `{offset}`. Default "Times are in {zone} ({offset})." */
  zoneNote?: string;
  /** The same while the offset is not known yet; `{zone}`. Default "Times are in {zone}." */
  zoneOnly?: string;
  /** Under the pickers; `{when}` is the earliest time. Default "Earliest: {when}." */
  earliest?: string;
  /** Refusal for a time inside the lead time; `{when}` is the earliest time. Default "That is too soon. The earliest time is {when}." */
  soon?: string;
  /** Refusal for a time that has passed. Default "That time has passed. The earliest time is {when}." */
  past?: string;
  /** A day and a time in one phrase; `{date}` and `{time}`. Default "{date} at {time}". */
  at?: string;
  /** The sentence for "now". Default "Goes out as soon as you confirm." */
  sentenceNow?: string;
  /** The sentence for a time; `{when}`, `{zone}`, `{relative}`. Default "Goes out {when}, {zone}, {relative}". */
  sentenceLater?: string;
  /** The same before the clock is known; `{when}`, `{zone}`. Default "Goes out {when}, {zone}". */
  sentenceLaterQuiet?: string;
  /** While the day or the time is missing. Default "Pick a day and a time to schedule it." */
  sentencePick?: string;
  /** While the time is refused. Default "Not scheduled yet. Pick a later time." */
  sentenceRefused?: string;
}

export const DEFAULT_LABELS = {
  legend: "When should it go out?",
  now: "Send now",
  nowHint: "Sent immediately, nothing to schedule.",
  later: "Schedule for later",
  laterHint: "Pick the day and time it goes out.",
  zoneNote: "Times are in {zone} ({offset}).",
  zoneOnly: "Times are in {zone}.",
  earliest: "Earliest: {when}.",
  soon: "That is too soon. The earliest time is {when}.",
  past: "That time has passed. The earliest time is {when}.",
  at: "{date} at {time}",
  sentenceNow: "Goes out as soon as you confirm.",
  sentenceLater: "Goes out {when}, {zone}, {relative}",
  sentenceLaterQuiet: "Goes out {when}, {zone}",
  sentencePick: "Pick a day and a time to schedule it.",
  sentenceRefused: "Not scheduled yet. Pick a later time.",
} satisfies Required<SendScheduleLabels>;

export type Words = Required<SendScheduleLabels>;

/** What is chosen: send now, or later at `at`, an ISO time with an offset ("2026-10-27T09:00:00+01:00"), or null while it is missing or refused. */
export interface SendScheduleValue {
  mode: "now" | "later";
  at: string | null;
}

/** A day and a time of day, as the house date time picker holds them. */
export interface Draft {
  date: Date | null;
  /** "HH:MM", 24-hour. */
  time: string | null;
}

/** A day and a time of day with no zone attached. */
export interface Wall {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}

export const pad = (value: number): string => String(value).padStart(2, "0");

/** Fills `{name}` marks in a sentence. A mark with no value stays as it is. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (mark, key: string) => values[key] ?? mark);
}

const formats = new Map<string, Intl.DateTimeFormat>();

/** A formatter that spells out the wall clock of a zone in numbers. "en-US" here only fixes the order of the parts we read back. */
function zoneFormat(timeZone: string): Intl.DateTimeFormat {
  let format = formats.get(timeZone);
  if (!format) {
    format = new Intl.DateTimeFormat("en-US", { timeZone, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit" });
    formats.set(timeZone, format);
  }
  return format;
}

/** The zone as given, or "UTC" when the browser does not know it. */
export function safeZone(timeZone: string): string {
  try {
    zoneFormat(timeZone);
    return timeZone;
  } catch {
    return "UTC";
  }
}

function read(timeZone: string, instant: number): Wall & { second: number } {
  const parts = zoneFormat(timeZone).formatToParts(new Date(instant));
  const get = (type: string) => Number(parts.find((part) => part.type === type)?.value);
  return { year: get("year"), month: get("month"), day: get("day"), hour: get("hour") % 24, minute: get("minute"), second: get("second") };
}

/** The wall clock in a zone at an instant (milliseconds since 1970). */
export function wallAt(timeZone: string, instant: number): Wall {
  const { second: _second, ...wall } = read(timeZone, instant);
  return wall;
}

/** How many minutes the zone is ahead of UTC at an instant: Amsterdam is 60 in winter and 120 in summer. */
export function offsetAt(timeZone: string, instant: number): number {
  const wall = read(timeZone, instant);
  const asUtc = Date.UTC(wall.year, wall.month - 1, wall.day, wall.hour, wall.minute, wall.second);
  return Math.round((asUtc - Math.floor(instant / 1000) * 1000) / 60_000);
}

/** The instant a wall clock reads in a zone. A time the clock skips (spring forward) lands an hour later, and one it repeats (fall back) is read as the second. */
export function instantOf(wall: Wall, timeZone: string): number {
  const guess = Date.UTC(wall.year, wall.month - 1, wall.day, wall.hour, wall.minute);
  const first = guess - offsetAt(timeZone, guess) * 60_000;
  return guess - offsetAt(timeZone, first) * 60_000;
}

/**
 * The first slot of the time list at or after an instant, as an instant. The list counts `step` minutes from midnight on the wall clock
 * of the zone, so the rounding is done there: on the UTC clock it would name a time the list does not offer in a zone that is not a
 * whole number of hours from UTC (Asia/Kolkata with a step of 60 minutes). Once the last slot of a day is passed it is the first of the next.
 */
export function nextSlot(instant: number, step: number, timeZone: string): number {
  const wall = wallAt(timeZone, Math.ceil(instant / 60_000) * 60_000);
  const minutes = Math.ceil((wall.hour * 60 + wall.minute) / step) * step;
  // Date.UTC carries minutes past midnight into the next day.
  const day = new Date(Date.UTC(wall.year, wall.month - 1, wall.day, 0, minutes));
  return instantOf({ year: day.getUTCFullYear(), month: day.getUTCMonth() + 1, day: day.getUTCDate(), hour: day.getUTCHours(), minute: day.getUTCMinutes() }, timeZone);
}

/** The instant a picked day and time stand for in a zone. */
export function instantOfDraft(date: Date, time: string, timeZone: string): number {
  const [hour, minute] = time.split(":").map(Number);
  return instantOf({ year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate(), hour: hour ?? 0, minute: minute ?? 0 }, timeZone);
}

/** "2026-10-27T09:00:00+01:00": the wall clock in the zone with the zone's offset at that instant. */
export function isoAt(timeZone: string, instant: number): string {
  const wall = wallAt(timeZone, instant);
  const offset = offsetAt(timeZone, instant);
  const size = Math.abs(offset);
  return `${wall.year}-${pad(wall.month)}-${pad(wall.day)}T${pad(wall.hour)}:${pad(wall.minute)}:00${offset < 0 ? "-" : "+"}${pad(Math.floor(size / 60))}:${pad(size % 60)}`;
}

/** The picker's day and time for an ISO time, read in the zone. Nothing for a missing or unreadable one. */
export function draftOf(at: string | null, timeZone: string): Draft {
  const instant = at === null ? Number.NaN : Date.parse(at);
  if (Number.isNaN(instant)) return { date: null, time: null };
  const wall = wallAt(timeZone, instant);
  return { date: new Date(wall.year, wall.month - 1, wall.day), time: `${pad(wall.hour)}:${pad(wall.minute)}` };
}

/** "GMT+1", "GMT+5:30" or "GMT". */
export function gmtLabel(offset: number): string {
  if (offset === 0) return "GMT";
  const size = Math.abs(offset);
  const minutes = size % 60;
  return `GMT${offset < 0 ? "-" : "+"}${Math.floor(size / 60)}${minutes ? `:${pad(minutes)}` : ""}`;
}

/** A day as a sentence wants it: "Tue 27 Oct". The parts are formatted as UTC, so nothing shifts. */
export function dayLabel(wall: Wall, locale: string): string {
  return new Intl.DateTimeFormat(locale, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" }).format(new Date(Date.UTC(wall.year, wall.month - 1, wall.day)));
}

/** "in 3 days", "tomorrow", "in 2 hours", "in 45 minutes": the distance from `now` to `at`, in the unit people would say it in. */
export function relative(now: number, at: number, locale: string): string {
  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  const minutes = Math.round((at - now) / 60_000);
  // Minutes up to an hour, and up to two hours unless it is a whole hour ("in 90 minutes", but "in 1 hour" and "in 2 hours").
  if (Math.abs(minutes) < 60 || (Math.abs(minutes) < 120 && minutes % 60 !== 0)) return formatter.format(minutes, "minute");
  const hours = Math.round(minutes / 60);
  if (Math.abs(hours) < 36) return formatter.format(hours, "hour");
  return formatter.format(Math.round(hours / 24), "day");
}

/** A `now` given as a Date, a number of milliseconds or ISO text, as milliseconds. */
export function millisecondsOf(now: Date | number | string): number {
  return typeof now === "number" ? now : now instanceof Date ? now.getTime() : Date.parse(now);
}
